.mp-page {
  height: 100dvh;
  overflow: hidden;
  display: grid;
  grid-template-rows: auto minmax(0, 1fr) auto auto;
  gap: clamp(10px, 1.4vh, 18px);
  padding: clamp(18px, 2.4vw, 36px);
  background: var(--mp-panel);
  color: var(--mp-ink);
  font-family: var(--mp-font-sans);
  font-size: clamp(13px, 1vw, 16px);
}
.mp-page > * { min-width: 0; }
.mp-head { display: grid; gap: 6px; }
.mp-eyebrow { margin: 0; font-size: 12px; font-weight: 600; letter-spacing: .16em; color: var(--mp-faint); }
.mp-title { margin: 0; font-size: clamp(24px, 2.6vw, 38px); line-height: 1.12; letter-spacing: -0.01em; font-weight: 700; }
.mp-sub { margin: 0; max-width: 70ch; font-size: clamp(13px, 1.05vw, 16px); line-height: 1.6; color: var(--mp-muted); }

.mp-body { min-height: 0; display: grid; grid-template-columns: minmax(0, 1.75fr) minmax(200px, 0.62fr); gap: clamp(14px, 2vw, 28px); }
.mp-detail { min-height: 0; display: grid; align-content: start; gap: 6px; padding: clamp(14px, 1.8vw, 26px); border: 1px solid var(--mp-border); border-radius: 20px; background: var(--mp-raised); }
.mp-era { margin: 0; font-size: 11px; font-weight: 600; letter-spacing: .14em; color: var(--mp-faint); }
.mp-event { margin: 0; font-size: clamp(19px, 2vw, 28px); line-height: 1.25; font-weight: 700; }
.mp-desc { margin: 0; font-size: clamp(13px, 1.05vw, 16px); line-height: 1.7; color: var(--mp-muted); }
.mp-why { margin-top: 8px; padding-top: 10px; border-top: 1px solid var(--mp-border); }
.mp-label { margin: 0 0 4px; font-size: 11px; font-weight: 600; letter-spacing: .12em; color: var(--mp-faint); }
.mp-why-text { margin: 0; font-size: 13px; line-height: 1.6; }
.mp-shift { min-height: 0; display: grid; align-content: start; gap: 6px; padding: clamp(12px, 1.5vw, 20px); border-left: 3px solid var(--mp-border-strong); border-radius: 0 16px 16px 0; background: var(--mp-raised); }
.mp-shift-text { margin: 0 0 6px; font-size: clamp(15px, 1.3vw, 19px); font-weight: 600; line-height: 1.4; }
.mp-count { margin: 0; font-size: 12px; color: var(--mp-faint); }
.mp-count b { font-family: var(--mp-font-mono); color: var(--mp-ink); }
.mp-misread { margin: 8px 0 0; padding-top: 8px; border-top: 1px solid var(--mp-border); font-size: 12px; line-height: 1.6; color: var(--mp-muted); }

.mp-timeline { position: relative; padding-top: 14px; }
.mp-timeline::before { content: ""; position: absolute; left: 0; right: 0; top: 0; height: 1px; background: var(--mp-border-strong); }
.mp-progress { position: absolute; left: 0; top: 0; height: 2px; width: 0; background: var(--mp-ink); transition: width 200ms ease; }
.mp-track { margin: 0; padding: 0; list-style: none; display: grid; grid-template-columns: repeat(8, minmax(0, 1fr)); gap: 6px; }
.mp-track li { min-width: 0; }
.mp-node { position: relative; width: 100%; min-width: 0; display: grid; gap: 2px; padding: 14px 6px 8px; border: 1px solid var(--mp-border); border-radius: 12px; background: var(--mp-panel); color: var(--mp-ink); font: inherit; text-align: center; cursor: pointer; transition: background-color 150ms ease, border-color 150ms ease, opacity 150ms ease; }
.mp-node::before { content: ""; position: absolute; left: 50%; top: -15px; width: 1px; height: 14px; background: var(--mp-border-strong); }
.mp-node:hover { border-color: var(--mp-ink); }
.mp-node:focus-visible { outline: 2px solid var(--mp-ink); outline-offset: 2px; }
.mp-year { font-family: var(--mp-font-mono); font-size: clamp(12px, 1vw, 15px); font-weight: 600; line-height: 1.2; }
.mp-node-label { font-size: 12px; line-height: 1.3; color: var(--mp-muted); overflow-wrap: anywhere; }
.mp-node[data-mp-state="hidden"] { border-style: dashed; }
.mp-node[data-mp-state="hidden"] .mp-year { color: var(--mp-faint); }
.mp-node[data-mp-state="hidden"] .mp-node-label { color: var(--mp-faint); }
.mp-node[data-mp-state="current"] { background: var(--mp-invert); border-color: var(--mp-invert); color: var(--mp-invert-ink); }
.mp-node[data-mp-state="current"] .mp-node-label { color: var(--mp-invert-ink); opacity: .78; }
.mp-node[data-mp-state="current"]::before { width: 2px; background: var(--mp-ink); }

.mp-foot { display: flex; flex-wrap: wrap; justify-content: space-between; align-items: center; gap: 10px 16px; font-size: 12px; color: var(--mp-muted); }
.mp-source { margin: 0; max-width: 68ch; }
.mp-controls { display: flex; flex-wrap: wrap; gap: 8px; }
.mp-btn { min-height: 40px; padding: 0 16px; border: 1px solid var(--mp-border-strong); border-radius: 12px; background: var(--mp-panel); color: var(--mp-ink); font: inherit; font-size: 14px; cursor: pointer; }
.mp-btn:hover { border-color: var(--mp-ink); }
.mp-btn-primary { background: var(--mp-invert); color: var(--mp-invert-ink); border-color: var(--mp-invert); }
.mp-btn:focus-visible { outline: 2px solid var(--mp-ink); outline-offset: 2px; }

html[data-mp-reduced-motion="true"] .mp-page,
html[data-mp-reduced-motion="true"] .mp-page * { transition: none !important; animation: none !important; }
@media (prefers-reduced-motion: reduce) {
  .mp-page, .mp-page * { transition: none; animation: none; }
}
@media (max-width: 980px) {
  .mp-body { grid-template-columns: minmax(0, 1fr); grid-template-rows: minmax(0, 1fr) auto; }
  .mp-shift { border-left-width: 1px; border-radius: 16px; }
  .mp-misread { display: none; }
  .mp-track { grid-template-columns: repeat(4, minmax(0, 1fr)); }
  .mp-timeline { padding-top: 10px; }
  .mp-timeline::before, .mp-progress { display: none; }
  .mp-node::before { display: none; }
}

