(function () {
  var NODES = [
    { era: '奠基', title: '1943 · 形式神经元模型', desc: 'McCulloch 与 Pitts 用阈值逻辑描述神经活动，为神经网络提供数学原型。', why: '把神经活动写成可计算的规则。', shift: '逻辑模型' },
    { era: '命名', title: '1956 · 达特茅斯会议', desc: 'McCarthy、Minsky、Shannon 等参会，“人工智能”一词确立，被视为学科起点。', why: '研究者相信智能可以被形式化研究。', shift: '学科确立' },
    { era: '第一次低潮', title: '1969 · 《Perceptrons》', desc: 'Minsky 与 Papert 指出单层感知机无法表达异或，神经网络研究进入低潮。', why: '表达能力被证明存在硬性上限。', shift: '连接主义 → 符号主义' },
    { era: '回归', title: '1986 · 反向传播', desc: 'Rumelhart、Hinton 与 Williams 系统阐述反向传播，多层网络可端到端训练。', why: '有了训练多层网络的通用方法。', shift: '符号主义 → 连接主义' },
    { era: '符号高峰', title: '1997 · 深蓝击败 Kasparov', desc: 'IBM 深蓝击败国际象棋世界冠军，符号搜索与专用硬件结合达到高峰。', why: '封闭规则下搜索加算力极强。', shift: '符号搜索高峰' },
    { era: '转折', title: '2012 · AlexNet', desc: 'AlexNet 在 ImageNet 夺冠，GPU 训练的大规模卷积网络证明深度学习有效。', why: '数据、算力与算法三要素合流。', shift: '手工特征 → 端到端学习' },
    { era: '架构', title: '2017 · Transformer', desc: '自注意力替代循环结构，支持高度并行训练，成为大语言模型的基础。', why: '并行化把算力真正释放出来。', shift: '循环结构 → 自注意力' },
    { era: '应用', title: '2022 · ChatGPT', desc: '大规模预训练加人类反馈对齐的对话模型进入大众应用。', why: '预训练规模与对齐方法结合。', shift: '专用任务 → 通用生成' }
  ];
  var root = document.querySelector('.mp-page');
  if (!root) { return; }
  var nodes = root.querySelectorAll('[data-mp-action="node"]');
  var eraEl = root.querySelector('[data-mp-role="era"]');
  var eventEl = root.querySelector('[data-mp-role="event"]');
  var descEl = root.querySelector('[data-mp-role="desc"]');
  var whyEl = root.querySelector('[data-mp-role="why"]');
  var shiftEl = root.querySelector('[data-mp-role="shift"]');
  var posEl = root.querySelector('[data-mp-role="pos"]');
  var barEl = root.querySelector('[data-mp-role="progress"]');
  var nextBtn = root.querySelector('[data-mp-action="next"]');
  var prevBtn = root.querySelector('[data-mp-action="prev"]');
  var resetBtn = root.querySelector('[data-mp-action="reset"]');
  var current = 0;
  var revealed = 0;

  function render() {
    root.dataset.mpState = revealed === 0 ? 'idle' : 'exploring';
    for (var i = 0; i < nodes.length; i += 1) {
      var btn = nodes[i];
      if (i === current) {
        btn.setAttribute('data-mp-state', 'current');
        btn.setAttribute('aria-current', 'true');
      } else {
        btn.setAttribute('data-mp-state', i <= revealed ? 'revealed' : 'hidden');
        btn.removeAttribute('aria-current');
      }
    }
    var n = NODES[current];
    eraEl.textContent = n.era;
    eventEl.textContent = n.title;
    descEl.textContent = n.desc;
    whyEl.textContent = n.why;
    shiftEl.textContent = n.shift;
    posEl.textContent = String(current + 1);
    if (barEl) {
      barEl.style.width = String((revealed / (NODES.length - 1)) * 100) + '%';
    }
  }

  function go(index) {
    var target = Math.max(0, Math.min(NODES.length - 1, index));
    current = target;
    if (target > revealed) { revealed = target; }
    render();
    window.MockFinal.emit('interaction', { id: 'timeline-reveal', index: current, revealed: revealed });
  }

  if (nextBtn) {
    nextBtn.addEventListener('click', function () { go(current + 1); });
  }
  if (prevBtn) {
    prevBtn.addEventListener('click', function () { go(current - 1); });
  }
  if (resetBtn) {
    resetBtn.addEventListener('click', function () {
      current = 0;
      revealed = 0;
      render();
      window.MockFinal.emit('interaction', { id: 'timeline-reveal', index: 0, revealed: 0 });
    });
  }
  for (var k = 0; k < nodes.length; k += 1) {
    nodes[k].addEventListener('click', function (event) {
      var raw = event.currentTarget.getAttribute('data-mp-index');
      go(Number(raw));
    });
  }

  if (typeof window.MockFinal.onHostMessage === 'function') {
    window.MockFinal.onHostMessage(function (msg) {
      if (msg && msg.type === 'theme') { render(); }
    });
  }

  render();
  window.MockFinal.ready({ title: '人工智能简史：八个转折节点' });
})();
